import networkx as nx

# Heawood graph via LCF notation [5,-5]^7
edges = []
n = 14
# Cycle edges
for i in range(n):
    edges.append((min(i, (i+1)%n), max(i, (i+1)%n)))
# Chord edges: for even i, connect to i+5 mod 14
